    onFocus={() => { original.current = value; }} onChange={event => onChange(event.target.value)} onBlur={() => setTouched(true)} onInvalid={() => setTouched(true)}
    onKeyDown={event => {
      if (event.nativeEvent.isComposing) return;
      if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); onChange(original.current); setTouched(false); }
      if (event.key === "Enter") { event.preventDefault(); event.stopPropagation(); setTouched(true); if (event.currentTarget.reportValidity()) event.currentTarget.blur(); }
    }} />;
}

